using UnityEngine;using UnityEngine.UI;using IdleIntelligence.Core;
namespace IdleIntelligence.Runtime {
 public sealed class ModelLoadout:MonoBehaviour {
  public RectTransform Network,Universal;public Image Core;public Text Name,Stats;GameRuntime game;GameState observed;float feedback=1;double receiptAt=-1000;bool changedIncome,changedData;public static readonly Vector2[] Positions={new Vector2(.17f,.76f),new Vector2(.5f,.83f),new Vector2(.83f,.76f),new Vector2(.17f,.24f),new Vector2(.5f,.17f),new Vector2(.83f,.24f)};
  public void Initialize(GameRuntime runtime){game=runtime;Core.raycastTarget=true;var training=Core.gameObject.GetComponent<Button>()??Core.gameObject.AddComponent<Button>();training.onClick.AddListener(()=>game.UserShow("training"));WorkshopUIFactory.Button("LoadoutBonuses",transform,game.State.Settings.language=="de"?"Aktive Ausrüstungsboni":"Active equipment bonuses",()=>game.WorkshopView.OpenBonuses());}
  public void Receipt(bool reduced,bool incomeChanged=false,bool dataChanged=false){changedIncome=incomeChanged;changedData=dataChanged;feedback=reduced?1:0;receiptAt=ReceiptMotion.Now-(reduced?1:0);}
  string Tint(string value,bool changed)=>changed&&feedback<.6f?"<color=#38EEA0>"+value+"</color>":value;
  void LateUpdate(){if(game==null)return;feedback=ReceiptMotion.Age(receiptAt);var s=game.State;if(ReferenceEquals(observed,s)&&feedback>=.6f)return;observed=s;Name.text=s.Retention.aiName+" · Lv. "+s.ModelLevel;Stats.text="Q "+Game.TrainingLevel(s,"quality")+"   E "+Game.TrainingLevel(s,"efficiency")+"   G "+Game.TrainingLevel(s,"integration")+"\n"+Tint(NumberFormatting.Format(Game.Income(s),s.Settings.numberFormat)+" C/s",changedIncome)+" · "+Tint(NumberFormatting.Format(Game.DataRate(s),s.Settings.numberFormat)+" D/s",changedData);Core.color=feedback<.28f?Color.Lerp(GameTheme.Accent,Color.white,feedback/.28f):Color.white;Stats.color=GameTheme.Text;Core.rectTransform.anchoredPosition=new Vector2(0,feedback<.28f?Mathf.Sin(feedback/.28f*Mathf.PI)*3:0);}
 }
}
